import { Component } from '@angular/core';
import { Credito } from '../../../../models/credito.model';
import { AutocompleteFieldComponent } from "../../../../shared/generic-form/autocomplete-field/autocomplete-field.component";
import { CreditoService } from '../../../../controllers/credito.service';
import { ActivatedRoute, Router } from '@angular/router';
import { LocalStorageService } from '../../../../services/localStorage/local-storage.service';
import { DatoPersonaFisica } from '../../../../models/dato.persona.fisica.model';
import { DatoPersonaMoral } from '../../../../models/dato.persona.moral.model';
import { DatoPersonaFisicaService } from '../../../../controllers/dato.persona.fisica.service';
import { DatoPersonaMoralService } from '../../../../controllers/dato.persona.moral.service';

@Component({
    selector: 'app-clientes-credito-form-nuevo',
    imports: [
        AutocompleteFieldComponent
    ],
    templateUrl: './form-nuevo.component.html',
    styleUrl: './form-nuevo.component.css'
})
export class ClientesCreditoFormNuevoComponent {
  credito: Partial<Credito> = {}
  personaFisica: Partial<DatoPersonaFisica> = {}
  personaMoral: Partial<DatoPersonaMoral> = {}

  extraDataSucursales = {
    conditionals: JSON.stringify([
      ['deleted_at', 'IS NULL', null],
    ])
  }
  extraData = {
    conditionals: JSON.stringify([
      ['deleted_at', 'IS NULL', null],
      ['created_at', '>=', (new Date()).getFullYear() + '-' + '01-01'],
      ['created_at', '<=', (new Date()).getFullYear() + '-' + '12-31'],
    ])
  }

  constructor(
    private controller: CreditoService,
    private personaFisicaController: DatoPersonaFisicaService,
    private personaMoralController: DatoPersonaMoralService,
    private route: ActivatedRoute,
    private router: Router,
    private storage: LocalStorageService,
  ) {}

  async onSubmit() {
    const credito = await this.controller.new(this.credito)

    if(!credito?.id) return;

    const creditoRelation = await this.controller.find(credito.id, ['productosFinancieros'])

    const userData = this.storage.getClienteUser();

    if(!creditoRelation){
      console.error('ERROR: la relacion con productos financieros no existe.')
    }
    if(creditoRelation?.productos_financieros?.regimen_fiscal === 'PERSONA FISICA CON ACTIVIDAD EMPRESARIAL'){

      this.personaFisica = {
        credito_id: credito?.id,
        datos_personal_id: userData?.datos_personales_id
      }

      const personaFisica = await this.personaFisicaController.new(this.personaFisica)

      this.router.navigate(['../editar/' + creditoRelation?.id], { relativeTo: this.route })
      console.log("SE CREO UN CREDITO PF")
    }
    if(creditoRelation?.productos_financieros?.regimen_fiscal === 'PERSONA MORAL'){

      this.personaMoral = {
        credito_id: credito?.id,
        representante_legal_id: userData?.datos_personales_id,

        usuario_id: 0,
        tipo_empresa: 'COMERCIO', // choose default from: 'INDUSTRIA', 'AGROINDUSTRIA', 'COMERCIO', 'SERVICIOS'
        nombre_comercial: '',
        razon_social: '0000000000',
        fecha_constitucion: '',

        referencia_domicilio: '',
        rfc: '0000000000',
        localidad: '',
        ciudad_id: 1,

        calle: '0000000000',
        colonia: '0000000000',
        codigo_postal: '0000000000',
        no_exterior: '0000000000',
        no_interior: '',

        domicilio_desde: '',
        local_tipo: 'PROPIO', // default among: 'PROPIO' | 'RENTADO' | 'FAMILIAR' | 'PRESTADO' | 'OTRO'
        local_renta_mensual: 0,
        local_contrato_inicio: '',
        local_contrato_fin: '',
        email: '0000000000@gmail.com',
        resumen_actividad_empresarial: '',
        fecha_inicio_operaciones: '01/01/01',
        fecha_inicio_inscripcion_sat: '',

        empleos_informales_mujeres: 0,
        empleos_informales_hombres: 0,
        empleos_informales_no_binarios: 0,

        empleos_imss_mujeres: 0,
        empleos_imss_hombres: 0,
        empleos_imss_no_binarios: 0,

        empleos_a_generar_mujeres: 0,
        empleos_a_generar_hombres: 0,
        empleos_a_generar_no_binarios: 0,

        latitud: null,
        longitud: null,
      }

      const personaMoral = await this.personaMoralController.new(this.personaMoral)

      this.router.navigate(['../editar/' + creditoRelation?.id], { relativeTo: this.route })
      console.log("SE CREO UN CREDITO PM")
    }
  }

  public cancelarCreacionCredito(){
    this.router.navigate(['/clientes/main/creditos/'])
  }
}
